"""Builds p3b3_apply.py: old strings are extracted from the real working source (so they are exact) and embedded as literals."""
import re, sys, pprint
SRC = sys.argv[1]
main = open(SRC + '/main.tex', 'rb').read().decode('utf-8').replace('\r\n', '\n')
tab = open(SRC + '/tables/table_computational_budget.tex', 'rb').read().decode('utf-8').replace('\r\n', '\n')
def cut(t, a, b):
    i = t.index(a); j = t.index(b, i) + len(b); assert t.count(t[i:j]) == 1; return t[i:j]
N = {}   # new texts
N['intro'] = (r"end-to-end and decoupled component latencies, effective token volumes, and financial costs across all",
              r"end-to-end and stage latencies, effective token volumes, and modelled financial costs across all")
old_cost = cut(main, "Across the 350-query benchmark, TERRA performs", "NLI grader and generator).")
new_cost = (r"Across the 350-query benchmark, TERRA performs \TerraOperationsTotalCount\ operations (\TerraOperationsPerQuery\ per query; operations counted where a stage recorded non-zero time) at a modelled \TerraDeployedCostPerThousand\ per 1,000 queries under the deployed configuration (Gemma~3 12B router; Llama~3.3 70B NLI grader and generator). The cost is modelled from token-count estimates at list prices, not metered; it prices a grader call for every Category~B--D query (twice for refused Category~C and~D queries) and none for Category~A, although Category~A recorded grading time. Pricing one grader call only where the recorded grading time was at least 1~ms gives \$4.66 per 1,000 queries instead.")
old_paths = cut(main, "Critically, both Category~C (unanswerable", "$ ops/query).\n")
# the closure paragraph ends with 'ops/query).' ; include through the sentence end
old_paths = cut(main, "Critically, both Category~C (unanswerable", "\\TerraOverallTotalOpsPerQuery$ ops/query).")
new_paths = (r"These counts are measured from recorded stage times, not taken from a design model. In the canonical run, Category~A (the nominal fast path) recorded retrieval and NLI-grader time on all 100 queries and invoked the generator on \TerraCatAGenCallsFormatted; Category~B recorded all four stages on all 100 queries and invoked the generator on \TerraCatBGenCallsFormatted; Category~C recorded routing, retrieval and grading time on all 75 queries but no generation, because all 75 were refused, and for 74 of them the recorded grading time was under 1~ms and the retrieved context was empty, which is consistent with a deterministic empty-context rejection rather than an LLM grading call; Category~D recorded all three pre-generation stages on all 75 queries and invoked the generator on \TerraCatDGenCallsFormatted, the other 46 queries being refused (7 of them with an empty context). This yields \TerraCatATotalOps, \TerraCatBTotalOps, \TerraCatCTotalOps\ and \TerraCatDTotalOps\ operations on Categories~A--D (\TerraCatATotalOpsPerQuery, \TerraCatBTotalOpsPerQuery, \TerraCatCTotalOpsPerQuery\ and \TerraCatDTotalOpsPerQuery\ per query) and \TerraBenchmarkTotalOpsFormatted\ in total (\TerraOverallTotalOpsPerQuery\ per query). A design-level model in which out-of-domain queries beyond the geometric boundary are terminated before retrieval is not what the deployed run did: every Category~C query recorded retrieval time (at least 178~ms excluding routing), so the threshold analysis in Panel~B describes an offline calibration of a candidate pre-filter.")
old_gen = cut(main, "Importantly, while TERRA executes more sequential pipeline stages", "aggregate serving efficiency.")
new_gen = (r"Importantly, while TERRA executes more sequential pipeline stages than single-shot baselines, it invokes the generator on only \TerraOverallGenCallsCount\ of the 350 benchmark queries (\TerraOverallGenCallsPct), a \TerraOverallGenCallsReductionPct\ reduction in active generator calls compared to the single-shot baselines ($350/350$). The reduction comes from refusals: Category~C made no generator calls (\TerraCatCGenCallsFormatted), Category~D made \TerraCatDGenCallsFormatted, and the refusals on Categories~A and~B also skip generation. It is not a reduction in total 70B-model use: the NLI grader is also a Llama~3.3 70B model and recorded at least 1~ms of grading time on 276 of the 350 queries, so TERRA's generator and grader calls together exceed the baselines' one call per query. We frame the generator-call reduction not as an alternative metric for call parity, but as one mitigating factor in aggregate serving efficiency.")
N['cost_label'] = (r"an operational cost of $\TerraCatBTotalCostPerThousand$ per 1,000 queries", r"a modelled cost of $\TerraCatBTotalCostPerThousand$ per 1,000 queries")
N['tradeoff'] = (r"expending $\sim \TerraHardPathMedianSeconds\text{ s}$ and approximately one cent per query to secure complete doctrinal authority is an operationally sound trade-off.",
                 r"expending $\sim \TerraHardPathMedianSeconds\text{ s}$ and roughly $\TerraCatBPerQueryCost$ per query (modelled) to recover the full precedent path on $\CatBTerraFullPathCount$ of the Category~B queries is, in our judgement, a defensible trade-off.")
N['title'] = (r"\subsubsection{Decoupled Wall-Clock Latency Profiling}", r"\subsubsection{Stage Latency Profiling}")
N['lead'] = (r"Panel~A decouples end-to-end wall-clock latency into four isolated execution stages, reconciling with reported benchmark totals within $0.02\text{ ms}$:",
             r"Panel~A reports mean stage times from the logged timing fields. For hard-route queries (Categories~B--D, 240 of 350) the logged retrieval timer is cumulative and includes routing time (the two correlate at $r=0.999$ across those queries, and the difference is always at least 178~ms), so retrieval is taken as logged retrieval time minus routing time; for fast-route queries the timers are separate. NLI grading and generation are the logged values. The stages sum exactly to the end-to-end time for Category~A and the single-shot baselines. For Categories~B--D they leave a remainder that is not attributed to any stage and whose cause was not established (mean $\TerraCatBRemainderMS\text{ ms}$, $\TerraCatCRemainderMS\text{ ms}$ and $\TerraCatDRemainderMS\text{ ms}$, respectively), so the columns do not reconcile exactly to the end-to-end means:")
old_ret = cut(main, "    \\item \\textbf{Isolated Graph Retrieval:}", "($\\TerraCatADecoupledRetrievalMS\\text{ ms}$).")
new_ret = (r"    \item \textbf{Graph Retrieval:} Retrieval latency, isolated from routing, averages $\TerraOverallDecoupledRetrievalMS\text{ ms}$ overall ($\TerraCatADecoupledRetrievalMS\text{ ms}$ on Category~A, $\TerraCatBDecoupledRetrievalMS\text{ ms}$ on Category~B, $\TerraCatCDecoupledRetrievalMS\text{ ms}$ on Category~C and $\TerraCatDDecoupledRetrievalMS\text{ ms}$ on Category~D). The Category~A fast path does not bypass retrieval: all 100 Category~A queries recorded retrieval time.")
old_nli = cut(main, "    \\item \\textbf{NLI Smart Grader Verification:}", "$\\TerraCatCMeanClampedChars$ clamped characters).")
new_nli = (r"    \item \textbf{NLI Smart Grader Verification:} Logged grading time averages $\TerraOverallDecoupledNliMS\text{ ms}$ overall ($\TerraCatADecoupledNliMS\text{ ms}$ on Category~A, $\TerraCatBDecoupledNliMS\text{ ms}$ on Category~B, $\TerraCatCDecoupledNliMS\text{ ms}$ on Category~C and $\TerraCatDDecoupledNliMS\text{ ms}$ on Category~D). Category~C's low mean reflects its contexts: 74 of 75 Category~C queries retrieved an empty context (mean $\TerraCatCMeanRawChars$ characters across all 75) and recorded grading time under 1~ms, consistent with a deterministic rejection rather than an LLM call. Category~D contexts are longer (mean $\TerraCatDMeanRawChars$ characters, none above the 60{,}000-character clamp), and its grading time is correspondingly higher.")
old_g4 = cut(main, "on Category~C, generator latency collapses to", "are halted at the NLI gate.")
new_g4 = (r"on Category~C, generator latency is $\TerraCatCDecoupledGenerationMS\text{ ms}$ because no Category~C query reached the generator.")
main_edits = [
 ("\\input{phase3_corrections_b2} % Phase 3 Batch 02 overrides (R28; R10)\n", "\\input{phase3_corrections_b2} % Phase 3 Batch 02 overrides (R28; R10)\n\\input{phase3_corrections_b3} % Phase 3 Batch 03 overrides (R13; Table XXI, section VII-M)\n"),
 N['intro'], (old_cost, new_cost), (old_paths, new_paths), (old_gen, new_gen), N['cost_label'], N['tradeoff'], N['title'], N['lead'],
 (old_ret, new_ret), (old_nli, new_nli), (old_g4, new_g4)]
tab_edits = [
 ("Decoupled Component Latency Breakdown, and Geometric Gate Calibration", "Stage Latency Breakdown, and Geometric Gate Calibration"),
 ("end-to-end and decoupled component latencies (wall-clock ms), effective prompt/completion tokens, and total pipeline financial costs.", "end-to-end and stage latencies (wall-clock ms), effective prompt/completion tokens, and modelled pipeline financial costs (token estimates at list prices, not metered)."),
 ("\\textbf{Decoupled Component Latency Breakdown (Mean ms)}", "\\textbf{Stage Latency (Mean ms)}"),
 ("\\textbf{Prompt / Compl.} & \\textbf{1k Queries} \\\\", "\\textbf{Prompt / Compl.} & \\textbf{1k Queries (Modelled)} \\\\"),
 (cut(tab, "Computational profiling, sequential operations, and latency decoupling", "(\\$0.60/1M tokens)."),
  r"Computational profiling and stage latencies across $N=350$ queries from the canonical v2 evaluation (\texttt{data/terra\_canonical\_v2\_eval.json}). Operations per query count each stage (routing, retrieval, NLI grading, generation) that recorded non-zero time. Generator calls count queries with non-zero generation time. Routing, NLI grading and generation are means of the logged timing fields. Retrieval is the logged retrieval time minus routing time for hard-route queries (whose retrieval timer includes routing) and the logged value otherwise. The stages sum to the end-to-end time for Category~A and the single-shot baselines; for Categories~B--D a remainder not attributed to any stage averages \TerraCatBRemainderMS, \TerraCatCRemainderMS\ and \TerraCatDRemainderMS\ ms. Category~A recorded retrieval and NLI-grader time on every query. Category~C recorded no generation; for 74 of 75 queries the context was empty and the recorded grading time was under 1~ms. Costs are modelled, not metered: token counts are estimated from character or word counts, Gemma 3 12B routing is priced at \$0.15/1M tokens and LLaMA 3.3 70B grading and generation at \$0.60/1M tokens, a grader call is priced for every Category~B--D query (twice for refused Category~C and~D queries) and none for Category~A, and retrieval is priced at \$0.00. Pricing one grader call only where the recorded grading time was at least 1~ms gives \$4.66 per 1,000 queries overall instead of \TerraDeployedCostPerThousand."),
]

old_pf1 = cut(main, "Under TERRA's operational threshold $\\tau=1.30$, the pre-filter functions", "responsibility of the downstream NLI Smart Grader.")
new_pf1 = (r"At the configured threshold $\tau=1.30$, the offline calibration shows zero in-domain false refusal and flags $\TerraGateTPRTauOneThreeZero$ ($\TerraGateTPRCountTauOneThreeZero$) of the out-of-domain probes by distance alone; the remaining $\TerraGateFNRTauOneThreeZero$ ($\TerraGateFNRCountTauOneThreeZero$) fall below the threshold. This is a calibration of a candidate pre-filter, not a description of the deployed run: in the canonical run every Category~C query recorded retrieval time (at least 178~ms excluding routing), so no query was terminated before retrieval, and all 75 Category~C queries were refused downstream, 74 of them on an empty retrieved context with a recorded grading time under 1~ms. Geometric proximity is an \textit{optional coarse pre-filter} intended to conserve retrieval and grading compute on obvious out-of-domain inputs; embedding distance does not prove legal validity or domain membership.")
old_pf2a = cut(main, "At the operational threshold $\\tau = 1.30$, geometric pre-filtering achieves", "of out-of-domain probes pre-retrieval.")
new_pf2a = (r"At the configured threshold $\tau = 1.30$, the offline calibration gives $\TerraGateFPRTauOneThreeZero$ in-domain false refusal ($\TerraGateFPRCountTauOneThreeZero$) and flags $\TerraGateTPRTauOneThreeZero$ ($\TerraGateTPRCountTauOneThreeZero$) of the out-of-domain probes by distance; the deployed run did not terminate any query before retrieval.")
old_pf2b = cut(main, "that saves retrieval and NLI compute on obvious outliers, while downstream", "indispensable primary safety firewall.")
new_pf2b = (r"that could save retrieval and NLI compute on obvious outliers. In the canonical run, 81 of the 139 refusals occurred on an empty retrieved context (74 in Category~C and 7 in Category~D) and 58 on a non-empty context (2, 16, 1 and 39 in Categories~A--D).")
main_edits += [(old_pf1, new_pf1), (old_pf2a, new_pf2a), (old_pf2b, new_pf2b)]
tab_edits.append(("\\textbf{TERRA Operational Setting: Zero false refusal on valid law; 54.7\\% OOD pre-filtered.}", "\\textbf{Configured threshold: zero false refusal on valid law; 54.7\\% of OOD probes flagged (offline calibration).}"))
tmpl = open('apply_template.py', encoding='utf-8').read()
out = tmpl.replace('@@MAIN_EDITS@@', pprint.pformat(main_edits, width=200)).replace('@@TAB_EDITS@@', pprint.pformat(tab_edits, width=200))
open('p3b3_apply.py', 'w', encoding='utf-8').write(out)
print('built', len(main_edits), 'main edits +', len(tab_edits), 'table edits')
